    "AB.FLOWERGIFT.name": "",  // Flower Gift
    "AB.FLOWERGIFT.desc": "Reforça os Pokémons do grupo quando está sol.",  // Powers up party Pokémon when it's sunny.
    "AB.BADDREAMS.name": "",  // Bad Dreams
